protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph) {
    List<E> edges = new ArrayList<E>(tour);
    V startVertex = null;
    V endVertex = null;
    for(E edge: edges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if(startVertex == null || source.equals(endVertex)) {
            startVertex = source;
            endVertex = target;
        } else if(target.equals(endVertex)) {
            endVertex = source;
        } else {
            throw new VertexNotFoundException();
        }
    }

    GraphPath<V,E> path = new GraphPath<V,E>(graph);
    path.addVertex(startVertex);
    path.addVertex(endVertex);
    for(E edge: edges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if(source.equals(endVertex)) {
            path.addEdge(edge);
            endVertex = target;
        }
    }

    return path;
}

